BEGIN
  DECLARE v_identity_rows INT64;
  DECLARE v_archive_rows INT64;
  DECLARE v_identity_unmatched INT64;
  DECLARE v_archive_unmatched INT64;

  ASSERT NULLIF(TRIM(p_pipeline_run_id),'') IS NOT NULL AS 'pipeline_run_id is required';
  ASSERT NULLIF(TRIM(p_export_run_id),'') IS NOT NULL AS 'export_run_id is required';
  ASSERT STARTS_WITH(p_archive_uri,'gs://rcb-bronze-zone/sap-interface-archive/')
    AS 'archive URI is outside the approved durable prefix';
  ASSERT STARTS_WITH(p_production_uri,'gs://interface-file/RCB_MOTOR/')
    AS 'production URI is outside the approved RCB_MOTOR prefix';
  ASSERT NULLIF(TRIM(p_archive_generation),'') IS NOT NULL
    AS 'archive generation evidence is required';
  ASSERT NULLIF(TRIM(p_production_generation),'') IS NOT NULL
    AS 'production generation evidence is required';
  ASSERT p_size_bytes>0 AS 'production object must be non-empty';
  ASSERT NULLIF(TRIM(p_crc32c),'') IS NOT NULL AS 'matching CRC32C evidence is required';
  ASSERT p_header_column_count=56 AS 'physical CSV must have exactly 56 header columns';
  ASSERT p_data_row_count>0 AS 'physical CSV must have at least one data row';
  ASSERT REGEXP_CONTAINS(p_production_file_name,
    r'^INSURANCE_RCB_[A-Za-z0-9._-]*[.]csv$')
    AS 'exact production filename must satisfy the INSURANCE_RCB CSV contract';
  ASSERT REGEXP_CONTAINS(p_sap_result_file_name,
    r'^RCB_MOTOR_INSURANCE_RCB_[A-Za-z0-9._-]*[.]csv$')
    AS 'exact SAP result filename must satisfy the RCB_MOTOR reporting contract';
  ASSERT REGEXP_CONTAINS(p_file_sha256,r'^[0-9A-Fa-f]{64}$')
    AS 'exact delivery SHA-256 evidence is required';
  ASSERT REGEXP_EXTRACT(p_production_uri,r'([^/]+)$')=p_production_file_name
    AS 'production filename must exactly equal the production object basename';
  ASSERT p_sap_result_file_name=CONCAT('RCB_MOTOR_',p_production_file_name)
    AS 'SAP result filename must be the approved BU reporting prefix plus production filename';

  SET v_identity_rows=(SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_payload_identity` i
    WHERE pipeline_run_id=p_pipeline_run_id AND file_role='NEWPAYMENT'
      AND NOT EXISTS (SELECT 1
        FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_balance_hold` h
        WHERE h.pipeline_run_id=p_pipeline_run_id AND h.order_item=i.order_item));
  SET v_archive_rows=(SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.export_archive`
    WHERE export_run_id=p_export_run_id
      AND delivery_status='ARCHIVED_PENDING_OBJECT_METADATA');
  SET v_identity_unmatched=(SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_payload_identity` i
    WHERE i.pipeline_run_id=p_pipeline_run_id AND i.file_role='NEWPAYMENT'
      AND NOT EXISTS (SELECT 1
        FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_balance_hold` h
        WHERE h.pipeline_run_id=p_pipeline_run_id AND h.order_item=i.order_item)
      AND NOT EXISTS (SELECT 1
        FROM `pacific-plating-282708.sap_integration_v3.export_archive` a
        WHERE a.export_run_id=p_export_run_id
          AND a.delivery_status='ARCHIVED_PENDING_OBJECT_METADATA'
          AND a.order_item=i.order_item AND a.period=i.period AND a.charge_id=i.charge_id
          AND a.payload_hash=i.payload_hash));
  SET v_archive_unmatched=(SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.export_archive` a
    WHERE a.export_run_id=p_export_run_id
      AND a.delivery_status='ARCHIVED_PENDING_OBJECT_METADATA'
      AND NOT EXISTS (SELECT 1
        FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_payload_identity` i
        WHERE i.pipeline_run_id=p_pipeline_run_id AND i.file_role='NEWPAYMENT'
          AND i.order_item=a.order_item AND i.period=a.period AND i.charge_id=a.charge_id
          AND i.payload_hash=a.payload_hash
          AND NOT EXISTS (SELECT 1
            FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_balance_hold` h
            WHERE h.pipeline_run_id=p_pipeline_run_id AND h.order_item=i.order_item)));
  ASSERT v_identity_rows>0 AS 'delivery cannot be marked for a zero-row run';
  ASSERT v_archive_rows=v_identity_rows
    AS 'archive ledger does not conserve against the same pipeline run identity';
  ASSERT v_identity_unmatched=0 AND v_archive_unmatched=0
    AS 'archive ledger identity set does not exactly match the same pipeline run payload';
  ASSERT p_data_row_count>=v_archive_rows
    AS 'physical CSV rows cannot be fewer than released event identities';
  ASSERT (SELECT COUNT(DISTINCT archive_uri)
    FROM `pacific-plating-282708.sap_integration_v3.export_archive`
    WHERE export_run_id=p_export_run_id)=1 AS 'export run has multiple archive URIs';
  ASSERT STARTS_WITH(p_archive_uri,(SELECT REGEXP_REPLACE(ANY_VALUE(archive_uri),r'[*][.]csv$','')
    FROM `pacific-plating-282708.sap_integration_v3.export_archive`
    WHERE export_run_id=p_export_run_id))
    AS 'archive object URI is outside the exact export-run URI pattern';
  ASSERT REGEXP_EXTRACT(p_archive_uri,r'([^/]+)$')=p_production_file_name
    AS 'archive and production basenames must match for exact-byte promotion';
  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.export_file_manifest`
    WHERE export_run_id=p_export_run_id OR production_uri=p_production_uri)=0
    AS 'manifest/export destination already recorded; refusing replay';
  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.sap_delivery_manifest_v3`
    WHERE export_run_id=p_export_run_id
      OR production_file_name=p_production_file_name
      OR sap_file_name=p_sap_result_file_name)=0
    AS 'SAP delivery manifest production/result filename or export run already recorded';

  BEGIN TRANSACTION;
  UPDATE `pacific-plating-282708.sap_integration_v3.export_archive`
  SET gcs_uri=p_production_uri,
      object_generation=p_production_generation,
      file_sha256=p_file_sha256,
      delivery_status='DELIVERED'
  WHERE export_run_id=p_export_run_id
    AND delivery_status='ARCHIVED_PENDING_OBJECT_METADATA';

  ASSERT @@row_count=v_archive_rows AS 'not every archive ledger row was marked DELIVERED';

  INSERT INTO `pacific-plating-282708.sap_integration_v3.export_file_manifest`
    (export_run_id,archive_uri,production_uri,archive_generation,production_generation,sha256,
     size_bytes,header_column_count,data_row_count,event_identity_count,uat2_status,delivery_status,
     recorded_at)
  VALUES
    (p_export_run_id,p_archive_uri,p_production_uri,p_archive_generation,p_production_generation,
     p_file_sha256,p_size_bytes,p_header_column_count,p_data_row_count,v_archive_rows,NULL,
     'DELIVERED',CURRENT_TIMESTAMP());

  INSERT INTO `pacific-plating-282708.sap_integration_v3.sap_delivery_manifest_v3`
    (export_run_id,production_uri,production_generation,sap_file_name,file_sha256,data_row_count,
     event_identity_count,delivery_status,recorded_at,production_file_name)
  VALUES
    (p_export_run_id,p_production_uri,p_production_generation,p_sap_result_file_name,p_file_sha256,
     p_data_row_count,v_archive_rows,'DELIVERED',CURRENT_TIMESTAMP(),p_production_file_name);
  COMMIT TRANSACTION;

  -- DELIVERED is only GCS evidence. PICKED_UP/ACKNOWLEDGED remain untouched until independent
  -- SAP result or refreshed mirror evidence is ingested. Deploy DDL 070 before this replacement.
END

BEGIN
  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
    WHERE log_id=p_log_id AND claim_token=p_claim_token)=1
    AS 'execution bind must reference exactly one claimed LogID/token';
  ASSERT REGEXP_CONTAINS(p_workflow_execution_name,
    r'^projects/([a-z][a-z0-9-]{4,28}[a-z0-9]|[0-9]{6,20})/locations/[a-z0-9-]+/workflows/[A-Za-z0-9_-]+/executions/[A-Za-z0-9_-]+$')
    AS 'workflow_execution_name must be a complete Workflows execution resource name';
  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
    WHERE workflow_execution_name=p_workflow_execution_name AND log_id!=p_log_id)=0
    AS 'workflow execution name is already bound to another LogID';

  BEGIN TRANSACTION;
  UPDATE `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
  SET request_status='STARTED',workflow_execution_name=p_workflow_execution_name
  WHERE log_id=p_log_id AND claim_token=p_claim_token AND request_status='CLAIMED';
  ASSERT @@row_count IN (0,1) AS 'execution bind affected an unexpected number of rows';
  COMMIT TRANSACTION;
  SELECT request_status,workflow_execution_name,export_run_id,sap_file_name
  FROM `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
  WHERE log_id=p_log_id AND claim_token=p_claim_token;
END

BEGIN
  DECLARE active_count INT64;
  DECLARE current_start DATE;
  DECLARE current_close TIMESTAMP;
  SET active_count=(SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.sap_period_lock`
    WHERE lock_datetime>CURRENT_TIMESTAMP());
  ASSERT active_count=1 AS 'Seed requires exactly one active legacy sap_period_lock row';
  ASSERT (SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.sap_period_state`)=0
    AS 'Seed is one-time only; sap_period_state is not empty';
  SET (current_start,current_close)=(SELECT AS STRUCT open_period_start,lock_datetime
    FROM `pacific-plating-282708.sap_integration_v3.sap_period_lock`
    WHERE lock_datetime>CURRENT_TIMESTAMP());
  ASSERT current_start=DATE_TRUNC(current_start,MONTH) AS 'Legacy open period is not month-aligned';
  ASSERT current_close>CURRENT_TIMESTAMP() AS 'Legacy closing time is not in the future';

  BEGIN TRANSACTION;
  INSERT INTO `pacific-plating-282708.sap_integration_v3.sap_period_state`
    (period_id,period_start,period_end,status,closing_at,closed_at,closed_by,state_version,
     created_at,updated_at)
  VALUES
    (FORMAT_DATE('%Y-%m',current_start),current_start,DATE_ADD(current_start,INTERVAL 1 MONTH),
     'OPEN',current_close,NULL,NULL,1,CURRENT_TIMESTAMP(),CURRENT_TIMESTAMP()),
    (FORMAT_DATE('%Y-%m',DATE_ADD(current_start,INTERVAL 1 MONTH)),
     DATE_ADD(current_start,INTERVAL 1 MONTH),DATE_ADD(current_start,INTERVAL 2 MONTH),
     'PLANNED',NULL,NULL,NULL,1,CURRENT_TIMESTAMP(),CURRENT_TIMESTAMP());
  ASSERT (SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.sap_period_state`
    WHERE status='OPEN')=1 AS 'Seed failed exact-one OPEN invariant';
  COMMIT TRANSACTION;
END

BEGIN
  DECLARE v_request_id STRING DEFAULT TRIM(p_request_id);
  DECLARE v_scope_hash STRING;
  ASSERT NULLIF(TRIM(p_request_id),'') IS NOT NULL AS 'request_id is required';
  ASSERT NULLIF(TRIM(p_requested_by),'') IS NOT NULL AS 'requested_by is required';
  ASSERT NULLIF(TRIM(p_source_reference),'') IS NOT NULL AS 'source_reference is required';
  ASSERT ARRAY_LENGTH(IFNULL(p_pairs,[]))=2295 AS 'scope must contain exactly 2,295 Mo pairs';
  ASSERT (SELECT COUNT(*) FROM UNNEST(p_pairs)
    WHERE NULLIF(TRIM(order_id),'') IS NULL OR period IS NULL OR period<1)=0
    AS 'scope contains a blank OrderID or invalid period';
  ASSERT (SELECT COUNT(*) FROM (
    SELECT TRIM(order_id),period,COUNT(*) n FROM UNNEST(p_pairs)
    GROUP BY 1,2 HAVING n!=1))=0 AS 'scope contains duplicate pairs';
  SET v_scope_hash=(SELECT LOWER(TO_HEX(SHA256(STRING_AGG(
    CONCAT(TRIM(order_id),'|',CAST(period AS STRING)),'\n'
    ORDER BY TRIM(order_id),period)))) FROM UNNEST(p_pairs));
  ASSERT v_scope_hash='33b91e08b301d3e37e3aa6acdf77d51cfb7f0fedda58862c92f8ddb3799cd9a8'
    AS 'scope does not equal the exact reviewed Mo 2,295-pair allowlist';

  BEGIN TRANSACTION;
    UPDATE `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_lock`
    SET claim_epoch=claim_epoch+1,claimed_at=CURRENT_TIMESTAMP()
    WHERE lock_name='MO_RCL_RECOVERY';
    ASSERT @@row_count=1 AS 'recovery lock is missing or duplicated';
    ASSERT (SELECT COUNT(*)
      FROM `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_request`
      WHERE request_id=v_request_id)=0 AS 'request_id is immutable and already exists';
    ASSERT (SELECT COUNT(*)
      FROM `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_scope`
      WHERE request_id=v_request_id)=0 AS 'request scope already exists';
    INSERT INTO `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_request`
      (request_id,requested_by,source_reference,expected_pair_count,request_status,created_at)
    VALUES (v_request_id,TRIM(p_requested_by),TRIM(p_source_reference),
      ARRAY_LENGTH(p_pairs),'SEEDED',CURRENT_TIMESTAMP());

    INSERT INTO `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_scope`
      (request_id,order_id,reported_period,captured_at)
    SELECT v_request_id,TRIM(order_id),period,CURRENT_TIMESTAMP()
    FROM UNNEST(p_pairs);
    ASSERT (SELECT COUNT(*)
      FROM `pacific-plating-282708.sap_integration_v3.mo_rcl_recovery_scope`
      WHERE request_id=v_request_id)=ARRAY_LENGTH(p_pairs) AS 'seed conservation failed';
  COMMIT TRANSACTION;
END

BEGIN
  ASSERT NULLIF(TRIM(p_pipeline_run_id),'') IS NOT NULL
    AS 'Units 2-5 wrapper requires pipeline_run_id';
  ASSERT (SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.pipeline_run_log`
    WHERE run_id=p_pipeline_run_id AND step='UNIT1_COMPLETE' AND status='SUCCESS')=1
    AS 'Units 2-5 wrapper requires exactly one successful UNIT1_COMPLETE for the same run';

  CALL `pacific-plating-282708.sap_integration_v3.sp_build_v3_unit2_shadow`(p_pipeline_run_id);
  CALL `pacific-plating-282708.sap_integration_v3.sp_evaluate_v3_unit2_magnitude`(
    p_pipeline_run_id);
  CALL `pacific-plating-282708.sap_integration_v3.sp_build_v3_unit3_mapping_holds`(p_pipeline_run_id);
  CALL `pacific-plating-282708.sap_integration_v3.sp_build_v3_notification_quarantine`(p_pipeline_run_id);
  CALL `pacific-plating-282708.sap_integration_v3.sp_evaluate_v3_automation_gate`(p_pipeline_run_id);
  CALL `pacific-plating-282708.sap_integration_v3.sp_build_v3_newpayment_shadow`(p_pipeline_run_id);

  -- Always rebuild delivery-ready, including 0 rows, so a healthy-zero night cannot leave the
  -- previous night's payload looking current.
  CALL `pacific-plating-282708.sap_integration_v3.sp_build_v3_newpayment_delivery_ready`(
    p_pipeline_run_id);
  IF (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_unit5_newpayment_delivery_ready`)>0 THEN
    CALL `pacific-plating-282708.sap_integration_v3.sp_export_v3_daily_newpayment_archive`(
      p_pipeline_run_id);
  END IF;
END

BEGIN
  DECLARE v_export_run_id STRING DEFAULT CONCAT('V3JULY-', FORMAT_TIMESTAMP('%Y%m%d-%H%M%S',CURRENT_TIMESTAMP()), '-', SUBSTR(GENERATE_UUID(),1,8));
  DECLARE v_file_name STRING;
  DECLARE v_archive_uri STRING;
  DECLARE export_rows INT64;

  CALL `pacific-plating-282708.sap_integration_v3.sp_build_july_export_shadow`();
  SET export_rows=(SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.july_export_ready`);
  ASSERT export_rows>0 AS 'No unexported July payment rows; no file written';
  ASSERT (SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.INFORMATION_SCHEMA.COLUMNS`
    WHERE table_name='july_export_ready')=56 AS 'Position contract failure: expected exactly 56 columns';

  SET v_file_name=CONCAT('INSURANCE_RCB_01_V3_JULY_PAYMENT_20260731_',v_export_run_id);
  SET v_archive_uri=CONCAT('gs://rcb-bronze-zone/sap-interface-archive/2026/07/31/',
    v_export_run_id,'/',v_file_name,'_*.csv');

  INSERT INTO `pacific-plating-282708.sap_integration_v3.export_archive`
    (export_run_id,order_item,period,charge_id,raw_payment_date,file_name,gcs_uri,archive_uri,delivery_folder,
     contract_version,payload_hash,payload_json,run_type,delivery_status,exported_at)
  SELECT v_export_run_id,e.order_item,e.period,e.charge_id,DATE(pe.charge_time),v_file_name,NULL,v_archive_uri,
    'RCB_MOTOR','SAP_INSURANCE_56_V1',TO_HEX(SHA256(TO_JSON_STRING(r))),TO_JSON_STRING(r),
    'MANUAL_JULY_CLOSE','PREPARED_ARCHIVE',CURRENT_TIMESTAMP()
  FROM `pacific-plating-282708.sap_integration_v3.expected_state` e
  JOIN `pacific-plating-282708.sap_integration_v3.stg_payment_events` pe USING(charge_id)
  JOIN `pacific-plating-282708.sap_integration_v3.july_export_ready` r
    ON r.OrderItem=e.order_item AND SAFE_CAST(r.Period AS INT64)=e.period
  WHERE DATE(pe.charge_time)>=DATE '2026-07-01' AND DATE(pe.charge_time)<DATE '2026-08-01';

  ASSERT (SELECT COUNT(*) FROM `pacific-plating-282708.sap_integration_v3.export_archive`
    WHERE export_run_id=v_export_run_id AND raw_payment_date>=DATE '2026-08-01')=0
    AS 'August raw PaymentDate in prepared archive; export aborted';

  EXECUTE IMMEDIATE FORMAT("""
    EXPORT DATA OPTIONS(uri='%s',format='CSV',overwrite=false,header=true)
    AS SELECT CompanyDB,OrderID,OrderItem,InvoiceNo,OrderDate,InsuredID,Title,FirstName,LastName,
      InsurerCode,InsuranceGroup,InsuranceType,InsuranceProduct,ProductType,PolicyType,Endorse,
      PolicyDate,PolicyNo,EndorsementNo,ChassisNo,LicensePlate,GrossPremium,StampDuty,VAT,
      TotalPremium,WHT,TotalEIR,TotalSBT,ProcessingFee,ProcessingFeeVat,ShippingFee,ShippingFeeVat,
      TotalAmount,Discount,TransactionStatus,SubmissionStatus,ApprovalStatus,PaymentStatus,
      ExpectedReceived,ActualReceived,InterestThisPeriod,PrincipleThisPeriod,InterestEIRThisPeriod,
      PrincipleEIRThisPeriod,PaymentDate,Period,TotalPeriods,PendingPayment,PaymentMethod,
      PaymentChannel,ExpectedDate,RefOrder,RefundAmountBeforeFee,RefundAmountAfterFee,BillingAddress,
      BatchRunDate
    FROM `pacific-plating-282708.sap_integration_v3.july_export_ready`
  """,v_archive_uri);

  UPDATE `pacific-plating-282708.sap_integration_v3.export_archive`
  SET delivery_status='ARCHIVED_PENDING_UAT2',exported_at=CURRENT_TIMESTAMP()
  WHERE export_run_id=v_export_run_id;
END

BEGIN
  ASSERT NULLIF(TRIM(p_error_template),'') IS NOT NULL AND LENGTH(p_error_template)<=300
    AS 'a sanitized error template of at most 300 characters is required';
  BEGIN TRANSACTION;
  UPDATE `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
  SET request_status=IF(attempt_count<3,'PENDING','HUMAN_ACTION'),
      completed_at=IF(attempt_count<3,NULL,CURRENT_TIMESTAMP()),
      last_error_template=p_error_template,claim_token=IF(attempt_count<3,NULL,claim_token),
      claimed_at=IF(attempt_count<3,NULL,claimed_at)
  WHERE log_id=p_log_id AND claim_token=p_claim_token AND request_status='CLAIMED';
  ASSERT @@row_count=1 AS 'claim release requires one matching CLAIMED row';
  COMMIT TRANSACTION;
END

BEGIN
  ASSERT p_terminal_status IN ('SUCCEEDED','TIMEOUT','HUMAN_ACTION')
    AS 'terminal status must be SUCCEEDED, TIMEOUT, or HUMAN_ACTION';
  ASSERT (p_terminal_status='SUCCEEDED' AND p_error_template IS NULL)
      OR (p_terminal_status!='SUCCEEDED' AND NULLIF(TRIM(p_error_template),'') IS NOT NULL)
    AS 'success must not carry an error; failure must carry a sanitized template';
  ASSERT p_error_template IS NULL OR LENGTH(p_error_template)<=300
    AS 'error template exceeds the sanitized 300-character limit';
  BEGIN TRANSACTION;
  UPDATE `pacific-plating-282708.sap_integration_v3.v3_post_import_refresh_outbox`
  SET request_status=p_terminal_status,completed_at=CURRENT_TIMESTAMP(),
      last_error_template=p_error_template
  WHERE log_id=p_log_id AND workflow_execution_name=p_workflow_execution_name
    AND request_status='STARTED';
  ASSERT @@row_count=1 AS 'completion requires one matching STARTED outbox row';
  COMMIT TRANSACTION;
END

BEGIN
  DECLARE hours_stale INT64;
  DECLARE last_ts TIMESTAMP;

  SET (hours_stale, last_ts) = (
    SELECT AS STRUCT hours_since_last_load, last_load_ts
    FROM `pacific-plating-282708.sap_integration_v3.vw_dead_mans_switch`
  );

  IF hours_stale > 26 THEN
    RAISE USING MESSAGE = FORMAT(
      'extract ไม่ได้รันคืนที่ %t (%d ชม.แล้ว) — กด EXECUTE ที่ https://console.cloud.google.com/run/jobs/details/asia-southeast1/sap-extract-job/executions?project=pacific-plating-282708',
      last_ts, hours_stale
    );
  END IF;
END

BEGIN
  DECLARE v_legacy_name STRING DEFAULT
    'projects/pacific-plating-282708/locations/asia-southeast1/jobs/sap-extract-schedule';
  DECLARE v_v3_name STRING DEFAULT
    'projects/pacific-plating-282708/locations/asia-southeast1/jobs/v3-nightly-orchestrator';

  ASSERT NULLIF(TRIM(p_approval_id),'') IS NOT NULL
    AND NULLIF(TRIM(p_approval_reference),'') IS NOT NULL
    AND NULLIF(TRIM(p_approved_by),'') IS NOT NULL
    AND NULLIF(TRIM(p_workflow_revision),'') IS NOT NULL
    AND NULLIF(TRIM(p_permission_rehearsal_execution_id),'') IS NOT NULL
    AS 'Common cutover approval requires exact identity and provenance';
  ASSERT STARTS_WITH(p_permission_rehearsal_execution_id,
      'projects/919786098205/locations/asia-southeast1/workflows/'
      ||'v3-nightly-orchestrator/executions/')
    AS 'Approval must bind the full immutable rehearsal execution resource';
  ASSERT p_approved_at<=CURRENT_TIMESTAMP() AND p_expires_at>CURRENT_TIMESTAMP()
    AS 'Common cutover approval must be current and unexpired';
  ASSERT REGEXP_CONTAINS(p_approved_commit,r'^[0-9a-f]{7,40}$')
    AS 'approved_commit must be an exact Git commit';
  ASSERT p_legacy_scheduler_name=v_legacy_name AND p_v3_scheduler_name=v_v3_name
    AND p_legacy_scheduler_name!=p_v3_scheduler_name
    AS 'Approval must name the exact distinct legacy and V3 Scheduler resources';
  ASSERT p_desired_schedule='30 20 * * *' AND p_desired_time_zone='Asia/Bangkok'
    AS 'Common V3 preparation must retain the approved 20:30 ICT anchor';
  ASSERT STARTS_WITH(p_manual_fallback,'sql/operator/')
    AS 'Approval requires a reviewed human fallback artifact';
  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.v3_common_cutover_approval`
    WHERE approval_id=p_approval_id)=0
    AS 'Common cutover approval ID already exists';

  INSERT INTO `pacific-plating-282708.sap_integration_v3.v3_common_cutover_approval`
  VALUES(p_approval_id,p_approval_reference,p_approved_by,p_approved_at,p_expires_at,
