  ASSERT (SELECT COUNT(*)
    FROM `pacific-plating-282708.sap_integration_v3.sap_delivery_manifest_v3`
    WHERE export_run_id=p_export_run_id AND sap_file_name=p_sap_file_name AND delivery_status='DELIVERED')=1
